window.docContents[251].resolve({"/2___-Basic-notions-of-representation-theory/2___8___-Quivers/Example-of-a-quiver/#Chapter2___Example2___8___2":{"contents":"Example 2.8.2.\n\n\\bullet \\longrightarrow \\bullet \\longleftarrow \\bullet\n\\uparrow\n\\bullet\n\n\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.8. Quivers\tExample of a quiver","header":"Example of a quiver","id":"/2___-Basic-notions-of-representation-theory/2___8___-Quivers/Example-of-a-quiver/#Chapter2___Example2___8___2"},"/5___-Representations-of-finite-groups___-Further-results/5___15___-The-Frobenius-character-formula/Section-5___15___-The-Frobenius-character-formula/#Chapter5___Introduction_5___15___heading-1":{"contents":"Let \\Delta(x) = \\prod_{1 \\leq i < j \\leq N} (x_i - x_j). Recall that \\Delta(x) is the Vandermonde determinant, \\det(x_i^{N-j}). Let \\rho = (N-1, N-2, \\ldots, 0) \\in \\mathbb{C}^N. The following theorem, due to Frobenius, gives a character formula for the Specht modules V_\\lambda.\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.15. The Frobenius character formula\tSection 5.15: The Frobenius character formula","header":"5.15. The Frobenius character formula","id":"/5___-Representations-of-finite-groups___-Further-results/5___15___-The-Frobenius-character-formula/Section-5___15___-The-Frobenius-character-formula/#Chapter5___Introduction_5___15___heading-1"}});
